import { describe, it, expect, vi, beforeEach } from 'vitest';
import {
  generateDesignChatResponse,
  generateAgentResponse,
  generateThinkingResponse,
  generateSearchResponse,
  generatePromptFromRefImages,
} from './chatService';
import { MODELS } from '../constants';
import type { Part } from '../types';

// Mock the api module
vi.mock('./api', () => ({
  api: {
    post: vi.fn(),
  },
}));

import { api } from './api';

describe('ChatService', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('generateDesignChatResponse', () => {
    it('should generate design chat response with simple prompt', async () => {
      const mockResponse = { text: 'Here is your design suggestion' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const result = await generateDesignChatResponse('Create a LinkedIn banner');

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/chat',
        expect.objectContaining({
          model: MODELS.openrouter.glm47,
          provider: 'openrouter',
          messages: expect.arrayContaining([
            expect.objectContaining({ role: 'system' }),
            expect.objectContaining({
              role: 'user',
              content: expect.arrayContaining([
                expect.objectContaining({ type: 'text', text: 'Create a LinkedIn banner' })
              ])
            }),
          ]),
        })
      );

      expect(result).toEqual({ text: 'Here is your design suggestion', groundingMetadata: null });
    });

    it('should include conversation history', async () => {
      const mockResponse = { text: 'Updated suggestion' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const history: { role: string; parts: Part[] }[] = [
        { role: 'user', parts: [{ text: 'Previous question' }] },
        { role: 'model', parts: [{ text: 'Previous answer' }] },
      ];

      await generateDesignChatResponse('Follow-up question', [], history);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/chat',
        expect.objectContaining({
          messages: expect.arrayContaining([
            expect.objectContaining({ role: 'system' }),
            expect.objectContaining({ role: 'user' }),
            expect.objectContaining({ role: 'assistant' }),
            expect.objectContaining({
              role: 'user',
              content: expect.arrayContaining([
                expect.objectContaining({ type: 'text', text: 'Follow-up question' })
              ])
            }),
          ]),
        })
      );
    });

    it('should include images in the message', async () => {
      const mockResponse = { text: 'Image analysis' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const images = ['https://example.com/image1.png', 'https://example.com/image2.png'];
      await generateDesignChatResponse('Analyze these images', images);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/chat',
        expect.objectContaining({
          messages: expect.arrayContaining([
            expect.objectContaining({
              role: 'user',
              content: expect.arrayContaining([
                expect.objectContaining({ type: 'text' }),
                expect.objectContaining({
                  type: 'image_url',
                  image_url: { url: 'https://example.com/image1.png' }
                }),
                expect.objectContaining({
                  type: 'image_url',
                  image_url: { url: 'https://example.com/image2.png' }
                }),
              ])
            }),
          ]),
        })
      );
    });

    it('should handle inline data images in history', async () => {
      const mockResponse = { text: 'Response with inline images' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const history: { role: string; parts: Part[] }[] = [
        {
          role: 'user',
          parts: [
            { text: 'Look at this' },
            {
              inlineData: {
                mimeType: 'image/png',
                data: 'base64data'
              }
            }
          ]
        },
      ];

      await generateDesignChatResponse('What do you think?', [], history);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/chat',
        expect.objectContaining({
          messages: expect.arrayContaining([
            expect.objectContaining({
              role: 'user',
              content: expect.arrayContaining([
                expect.objectContaining({ type: 'text', text: 'Look at this' }),
                expect.objectContaining({
                  type: 'image_url',
                  image_url: { url: 'data:image/png;base64,base64data' }
                }),
              ])
            }),
          ]),
        })
      );
    });

    it('should include system instruction with profile zone constraint', async () => {
      const mockResponse = { text: 'Design advice' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      await generateDesignChatResponse('Help me design');

      const call = vi.mocked(api.post).mock.calls[0][1];
      const systemMessage = call.messages[0];

      expect(systemMessage.role).toBe('system');
      expect(systemMessage.content[0].text).toContain('design');
      expect(systemMessage.content[0].text).toContain('profile');
    });

    it('should handle API errors', async () => {
      vi.mocked(api.post).mockRejectedValueOnce(new Error('API Error'));

      await expect(
        generateDesignChatResponse('Test prompt')
      ).rejects.toThrow('API Error');
    });
  });

  describe('generateAgentResponse', () => {
    it('should generate agent response with text only', async () => {
      const mockResponse = { text: 'Agent response' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const result = await generateAgentResponse('Create a banner', null);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/chat',
        expect.objectContaining({
          model: MODELS.openrouter.glm47,
          provider: 'openrouter',
          messages: expect.arrayContaining([
            expect.objectContaining({
              role: 'system',
              content: expect.stringContaining('Nano')
            }),
            expect.objectContaining({
              role: 'user',
              content: expect.arrayContaining([
                expect.objectContaining({ type: 'text', text: 'Create a banner' })
              ])
            }),
          ]),
        })
      );

      expect(result).toEqual({ text: 'Agent response' });
    });

    it('should include screenshot when provided', async () => {
      const mockResponse = { text: 'Response with screenshot context' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const screenshot = 'data:image/png;base64,screenshot';
      await generateAgentResponse('What do you see?', screenshot);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/chat',
        expect.objectContaining({
          messages: expect.arrayContaining([
            expect.objectContaining({
              role: 'user',
              content: expect.arrayContaining([
                expect.objectContaining({ type: 'text' }),
                expect.objectContaining({
                  type: 'image_url',
                  image_url: { url: screenshot }
                }),
              ])
            }),
          ]),
        })
      );
    });

    it('should include conversation history', async () => {
      const mockResponse = { text: 'Follow-up response' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const history: { role: string; parts: Part[] }[] = [
        { role: 'user', parts: [{ text: 'First message' }] },
        { role: 'model', parts: [{ text: 'First response' }] },
      ];

      await generateAgentResponse('Second message', null, history);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/chat',
        expect.objectContaining({
          messages: expect.arrayContaining([
            expect.objectContaining({ role: 'system' }),
            expect.objectContaining({ role: 'user', content: 'First message' }),
            expect.objectContaining({ role: 'assistant', content: 'First response' }),
            expect.objectContaining({
              role: 'user',
              content: expect.arrayContaining([
                expect.objectContaining({ text: 'Second message' })
              ])
            }),
          ]),
        })
      );
    });

    it('should handle empty parts in history', async () => {
      const mockResponse = { text: 'Response' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const history: { role: string; parts: Part[] }[] = [
        { role: 'user', parts: [] },
      ];

      await generateAgentResponse('Test', null, history);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/chat',
        expect.objectContaining({
          messages: expect.arrayContaining([
            expect.objectContaining({ role: 'user', content: '' }),
          ]),
        })
      );
    });

    it('should handle API errors', async () => {
      vi.mocked(api.post).mockRejectedValueOnce(new Error('Network error'));

      await expect(
        generateAgentResponse('Test', null)
      ).rejects.toThrow('Network error');
    });
  });

  describe('generateThinkingResponse', () => {
    it('should generate thinking response', async () => {
      const mockResponse = { text: 'Deep thinking analysis' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const result = await generateThinkingResponse('Complex problem to solve');

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/chat',
        expect.objectContaining({
          model: MODELS.openrouter.glm47,
          provider: 'openrouter',
          messages: [
            { role: 'system', content: 'You are a deep thinking assistant.' },
            { role: 'user', content: 'Complex problem to solve' },
          ],
        })
      );

      expect(result).toEqual({
        text: 'Deep thinking analysis',
        groundingMetadata: null
      });
    });

    it('should handle API errors', async () => {
      vi.mocked(api.post).mockRejectedValueOnce(new Error('Thinking failed'));

      await expect(
        generateThinkingResponse('Problem')
      ).rejects.toThrow('Thinking failed');
    });
  });

  describe('generateSearchResponse', () => {
    it('should generate search response with Perplexity model', async () => {
      const mockResponse = { text: 'Search results with sources' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const result = await generateSearchResponse('Latest LinkedIn trends 2026');

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/chat',
        expect.objectContaining({
          model: MODELS.openrouter.sonarDeepResearch,
          provider: 'openrouter',
          messages: expect.arrayContaining([
            expect.objectContaining({
              role: 'system',
              content: expect.arrayContaining([
                expect.objectContaining({
                  type: 'text',
                  text: expect.stringContaining('Trend Researcher')
                })
              ])
            }),
            expect.objectContaining({
              role: 'user',
              content: expect.arrayContaining([
                expect.objectContaining({
                  type: 'text',
                  text: 'Latest LinkedIn trends 2026'
                })
              ])
            }),
          ]),
        })
      );

      expect(result).toEqual({
        text: 'Search results with sources',
        groundingMetadata: null
      });
    });

    it('should include conversation history', async () => {
      const mockResponse = { text: 'More search results' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const history: { role: string; parts: Part[] }[] = [
        { role: 'user', parts: [{ text: 'Previous search' }] },
        { role: 'model', parts: [{ text: 'Previous results' }] },
      ];

      await generateSearchResponse('Follow-up search', history);

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/chat',
        expect.objectContaining({
          messages: expect.arrayContaining([
            expect.objectContaining({ role: 'system' }),
            expect.objectContaining({
              role: 'user',
              content: expect.arrayContaining([
                expect.objectContaining({ type: 'text', text: 'Previous search' })
              ])
            }),
            expect.objectContaining({
              role: 'assistant',
              content: expect.arrayContaining([
                expect.objectContaining({ type: 'text', text: 'Previous results' })
              ])
            }),
            expect.objectContaining({
              role: 'user',
              content: expect.arrayContaining([
                expect.objectContaining({ type: 'text', text: 'Follow-up search' })
              ])
            }),
          ]),
        })
      );
    });

    it('should filter out non-text parts from history', async () => {
      const mockResponse = { text: 'Search results' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const history: { role: string; parts: Part[] }[] = [
        {
          role: 'user',
          parts: [
            { text: 'Text part' },
            { inlineData: { mimeType: 'image/png', data: 'base64' } }
          ]
        },
      ];

      await generateSearchResponse('Search query', history);

      const call = vi.mocked(api.post).mock.calls[0][1];
      const userMessage = call.messages.find((m: any) => m.role === 'user' && m.content.some((c: any) => c.text === 'Text part'));

      expect(userMessage).toBeDefined();
      expect(userMessage.content).toHaveLength(1);
      expect(userMessage.content[0].text).toBe('Text part');
    });

    it('should handle API errors', async () => {
      vi.mocked(api.post).mockRejectedValueOnce(new Error('Search failed'));

      await expect(
        generateSearchResponse('Query')
      ).rejects.toThrow('Search failed');
    });
  });

  describe('generatePromptFromRefImages', () => {
    it('should generate prompt from reference images', async () => {
      const mockResponse = { text: 'Generated prompt based on images' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const images = [
        'https://example.com/ref1.png',
        'https://example.com/ref2.png'
      ];
      const result = await generatePromptFromRefImages(images, 'corporate style');

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/chat',
        expect.objectContaining({
          model: MODELS.openrouter.glm47,
          provider: 'openrouter',
          messages: [
            expect.objectContaining({
              role: 'user',
              content: expect.arrayContaining([
                expect.objectContaining({
                  type: 'text',
                  text: expect.stringContaining('corporate style')
                }),
                expect.objectContaining({
                  type: 'image_url',
                  image_url: { url: 'https://example.com/ref1.png' }
                }),
                expect.objectContaining({
                  type: 'image_url',
                  image_url: { url: 'https://example.com/ref2.png' }
                }),
              ])
            }),
          ],
        })
      );

      expect(result).toBe('Generated prompt based on images');
    });

    it('should include user hint in analysis request', async () => {
      const mockResponse = { text: 'Prompt based on minimalist style' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      await generatePromptFromRefImages(['https://example.com/image.png'], 'minimalist');

      const call = vi.mocked(api.post).mock.calls[0][1];
      const content = call.messages[0].content[0];

      expect(content.text).toContain('minimalist');
      expect(content.text).toContain('Analyze');
      expect(content.text).toContain('prompt');
    });

    it('should handle single image', async () => {
      const mockResponse = { text: 'Single image analysis' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      await generatePromptFromRefImages(['https://example.com/single.png'], 'elegant');

      expect(api.post).toHaveBeenCalledWith(
        '/api/ai/chat',
        expect.objectContaining({
          messages: [
            expect.objectContaining({
              content: expect.arrayContaining([
                expect.objectContaining({ type: 'text' }),
                expect.objectContaining({ type: 'image_url' }),
              ])
            }),
          ],
        })
      );
    });

    it('should handle multiple images', async () => {
      const mockResponse = { text: 'Multi-image analysis' };
      vi.mocked(api.post).mockResolvedValueOnce(mockResponse);

      const images = [
        'https://example.com/img1.png',
        'https://example.com/img2.png',
        'https://example.com/img3.png',
      ];

      await generatePromptFromRefImages(images, 'modern');

      const call = vi.mocked(api.post).mock.calls[0][1];
      const content = call.messages[0].content;

      expect(content).toHaveLength(4); // 1 text + 3 images
      expect(content.filter((c: any) => c.type === 'image_url')).toHaveLength(3);
    });

    it('should handle API errors', async () => {
      vi.mocked(api.post).mockRejectedValueOnce(new Error('Image analysis failed'));

      await expect(
        generatePromptFromRefImages(['https://example.com/img.png'], 'hint')
      ).rejects.toThrow('Image analysis failed');
    });
  });
});
